# --- Receipt/Document Guardrail (Python Code node) ---
# Mode: Run Once for All Items. Needs stdlib allow: re, datetime
import re
from datetime import datetime, timedelta, timezone

# --- Config ---
MAURITIUS_TZ = timezone(timedelta(hours=4))  # Mauritius has no daylight saving
CONFIDENCE_THRESHOLD = 0.7
ALLOWED_CATEGORIES = {
    "groceries", "dining", "transport", "fuel", "utilities", "rent", "telecom",
    "health", "education", "clothing", "household", "entertainment",
    "subscriptions", "gifts", "festival", "salary", "other",
}
SOURCE_BY_INPUT_TYPE = {"receipt": "receipt", "document": "document",
                        "voiceNote": "voice"}
ALLOWED_DOC_TYPES = {"payslip", "receipt", "purchase"}


# --- Helpers ---
def today_in_mauritius():
    return datetime.now(MAURITIUS_TZ).strftime("%Y-%m-%d")


def clean_date(raw_date):
    """Return (YYYY-MM-DD, where the date came from)."""
    if isinstance(raw_date, str) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw_date):
        try:
            datetime.strptime(raw_date, "%Y-%m-%d")
            return raw_date, "provided"
        except ValueError:
            pass
    return today_in_mauritius(), "defaulted"


def to_int_cents(value):
    try:
        return int(round(float(value)))
    except (TypeError, ValueError):
        return 0


def to_positive_qty(value):
    try:
        quantity = float(value)
    except (TypeError, ValueError):
        return 1.0
    return quantity if quantity > 0 else 1.0


# --- Input: AI output merged with the verified request ---
merged_item = _items[0]["json"]
ai_output = merged_item.get("output", merged_item)  # some n8n versions nest it

line_items = []
for raw_line in ai_output.get("lineItems") or []:
    category = str(raw_line.get("category") or "other").strip().lower()
    line_items.append({
        "name": raw_line.get("name") or "item",
        "price": to_int_cents(raw_line.get("price")),
        "qty": to_positive_qty(raw_line.get("qty")),
        "category": category if category in ALLOWED_CATEGORIES else "other",
        "direction": "income" if raw_line.get("direction") == "income" else "expense",
    })

claimed_total = to_int_cents(ai_output.get("claimedTotalCents"))
confidence = float(ai_output.get("confidenceScore") or 0)  # missing score fails safe
txn_date, date_source = clean_date(ai_output.get("txnDate"))

# --- Deterministic checks (integer cents, no floats saved) ---
calculated_total = sum(
    int(round(line["price"] * line["qty"])) for line in line_items
)

flags = []
if not line_items:
    flags.append("No line items were read.")
elif calculated_total <= 0:
    flags.append("No amount was read.")
if calculated_total != claimed_total:
    flags.append("Line items do not sum to the stated total.")
if confidence < CONFIDENCE_THRESHOLD:
    flags.append("AI confidence below 0.7.")

doc_type = str(ai_output.get("docType") or merged_item.get("docType") or "").strip().lower()
summary = str(ai_output.get("summary") or merged_item.get("summary") or "").strip()

# --- Output: a preview only. Saving happens on the confirmTransaction route. ---
return [{"json": {
    "success": True,
    "saved": False,
    "record": "preview",
    "docType": doc_type if doc_type in ALLOWED_DOC_TYPES else "purchase",
    "summary": summary or "The AI could not describe this input.",
    "lowConfidence": confidence < CONFIDENCE_THRESHOLD,
    "vendor": ai_output.get("vendor"),
    "totalCents": calculated_total,
    "lineItems": line_items,
    "flags": flags,
    "requiresValidation": len(flags) > 0,
    "txnDate": txn_date,
    "dateSource": date_source,
    "confidenceScore": confidence,
    "source": SOURCE_BY_INPUT_TYPE.get(merged_item.get("inputType"), "document"),
}}]

# --- Build Acknowledgement (Python Code node, right before Final Respond) ---
# Every branch ends here. Detects what arrived and returns a short receipt.
# Mode: Run Once for All Items. No imports needed.

incoming = [entry["json"] for entry in _items]
first = incoming[0] if incoming else {}


def ack(record, saved, message_key, **extra):
    return [{"json": {"success": True, "saved": saved, "record": record,
                      "messageKey": message_key, **extra}}]


# --- Transactions inserted (one item per saved transaction) ---
if "amount" in first and "direction" in first:
    return ack("transaction", True, "TRANSACTION_SAVED",
               count=len(incoming),
               totalCents=sum(int(doc.get("amount", 0)) for doc in incoming),
               ids=[doc.get("id") or doc.get("_id") for doc in incoming])

# --- Goal upserted (a goal document has targetAmount; the afford result does not) ---
if "goalKey" in first and "targetAmount" in first:
    return ack("goal", True, "GOAL_SAVED",
               goalKey=first.get("goalKey"),
               savedAmountCents=first.get("savedAmount"),
               verdict=first.get("verdict"),
               itemName=first.get("itemName"),
               timelineMonths=first.get("timelineMonths"),
               status=first.get("status"))

# --- Profile upserted (Firebase onboarding) ---
if "salary" in first and "bufferWeeks" in first:
    return ack("profile", True, "PROFILE_SAVED")

# --- Monthly expense list saved (Financial Overview) ---
if "monthlyExpenses" in first:
    expenses = first.get("monthlyExpenses") or []
    return ack("expenses", True, "EXPENSES_SAVED", count=len(expenses),
               totalCents=sum(int(e.get("amountCents") or 0) for e in expenses))

# --- Salary edited (Financial Overview) ---
if "salary" in first:
    return ack("salary", True, "SALARY_SAVED", salaryCents=first.get("salary"))

# --- Afford question: nothing saved, return the verdict ---
if "verdict" in first:
    return ack("afford", False, "AFFORD_" + str(first["verdict"]),
               verdict=first["verdict"],
               monthsNeeded=first.get("monthsNeeded"),
               safeToSpendCents=first.get("safeToSpend"),
               reachable=first.get("reachable", True))

# --- Spending summary: nothing saved ---
if "topMovers" in first or "summaryData" in first:
    return ack("summary", False, "SUMMARY_READY",
               summary=first.get("topMovers"))

return ack("unknown", False, "NOTHING_TO_SAVE")
